import test from 'node:test';import assert from 'node:assert/strict';import {Feedback} from '../src/feedback.js';
const game={state:'playing',room:1,width:960,height:600,player:{x:400,y:300,ammo:0},mods:{capacity:100}};
test('feedback expires, pauses and resets without mutating gameplay',()=>{const f=new Feedback(),g=structuredClone(game);f.event({type:'foam-boost',x:200,y:200},g);const snapshot=JSON.stringify(g);f.update(.4,g);assert.equal(JSON.stringify(g),snapshot);g.state='paused';const life=f.labels[0].life;f.update(2,g);assert.equal(f.labels[0].life,life);g.state='playing';f.update(2,g);assert.equal(f.labels.length,0);f.event({type:'clear'},g);f.event({type:'room'},g);assert.equal(f.clearAge,-1);});
test('many same-frame combo events do not flood labels; separated kills do not pretend to be a streak',()=>{const f=new Feedback();for(let i=0;i<100;i++)f.event({type:'bubble-pop',x:i,y:200},game);assert.equal(f.labels.length,1);f.event({type:'burst',x:200,y:200},game);f.update(1,game);f.event({type:'burst',x:200,y:200},game);assert.equal(f.streak,1);f.event({type:'burst',x:200,y:200},game);assert.equal(f.streak,2);assert.equal(f.labels.filter(l=>l.streak).length,1);});
